script:
# fetch_transit_time — Harvest -> Receiving transit, per greenhouse.
# Live schema: no custom_harvest_batch_no. Link harvest to receiving by
# custom_bucket_id on the same posting_date (same session). Anchored on
# Receiving (date-indexed) with a batch harvest lookup — no per-row subqueries.
try:
    from_date = frappe.form_dict.get("from_date") or frappe.utils.today()
    to_date   = frappe.form_dict.get("to_date")   or frappe.utils.today()

    recv_rows = frappe.db.sql(
        "SELECT r.posting_date, r.posting_time, r.farm AS farm,"
        "  r.custom_greenhouse AS greenhouse, r.custom_bucket_id AS bucket_id"
        " FROM `tabStock Entry` r"
        " WHERE r.stock_entry_type IN ('Receiving','Late Receipt') AND r.docstatus = 1"
        "   AND r.posting_date BETWEEN %(from_date)s AND %(to_date)s"
        "   AND r.custom_bucket_id > '' AND r.farm > '' AND r.custom_greenhouse > ''"
        " ORDER BY r.posting_date DESC, r.posting_time DESC LIMIT 20000",
        {"from_date": from_date, "to_date": to_date}, as_dict=1)

    rows_out = []
    if recv_rows:
        # Harvest lookup by date range (indexed) — NOT a giant bucket IN list,
        # which does not scale past a few thousand buckets. Keyed bucket|date.
        harvest_map = {}
        hrows = frappe.db.sql(
            "SELECT h.custom_bucket_id AS bucket_id, h.posting_date, h.posting_time"
            " FROM `tabStock Entry` h"
            " WHERE h.stock_entry_type = 'Harvesting' AND h.docstatus = 1"
            "   AND h.posting_date BETWEEN %(from_date)s AND %(to_date)s"
            "   AND h.custom_bucket_id > ''"
            " ORDER BY h.posting_time ASC",
            {"from_date": from_date, "to_date": to_date}, as_dict=1)
        for hr in hrows:
            k = str(hr.get("bucket_id") or "") + "|" + str(hr.get("posting_date") or "")
            if k not in harvest_map:
                harvest_map[k] = hr

        def fmt_time(t_val):
            if not t_val:
                return ""
            raw = str(t_val)
            if "," in raw:
                raw = raw.split(",")[1].strip()
            if "." in raw:
                raw = raw.split(".")[0]
            parts = raw.strip().split(":")
            if len(parts) == 3:
                return str(parts[0]).zfill(2) + ":" + str(parts[1]).zfill(2) + ":" + str(parts[2]).zfill(2)
            if len(parts) == 2:
                return str(parts[0]).zfill(2) + ":" + str(parts[1]).zfill(2) + ":00"
            return ""

        def mins_between(d1, t1, d2, t2):
            if not d1 or not t1 or not d2 or not t2:
                return None
            try:
                x = frappe.utils.get_datetime(str(d1) + " " + fmt_time(t1))
                y = frappe.utils.get_datetime(str(d2) + " " + fmt_time(t2))
                return int((y - x).total_seconds()) // 60
            except Exception:
                return None

        for r in recv_rows:
            k = str(r.get("bucket_id") or "") + "|" + str(r.get("posting_date") or "")
            h = harvest_map.get(k)
            if not h:
                continue
            m = mins_between(h.get("posting_date"), h.get("posting_time"),
                             r.get("posting_date"), r.get("posting_time"))
            if m is None or m < 0 or m > 1440:
                continue
            rows_out.append({"greenhouse": r.get("greenhouse") or "",
                             "farm": r.get("farm") or "", "transit_minutes": m})

    frappe.response["message"] = {"rows": rows_out, "total": len(rows_out)}
except Exception as e:
    frappe.log_error(str(e), "fetch_transit_time")
    frappe.response["message"] = {"rows": [], "error": str(e)}

# fetch_complete_timeline — Harvest -> end-of-journey (latest of Receiving or
# Shelving), per greenhouse. Live schema: link by custom_bucket_id; farm not
# custom_farm. Anchored on Receiving, batch harvest + shelf lookups.
try:
    from_date = frappe.form_dict.get("from_date") or frappe.utils.today()
    to_date   = frappe.form_dict.get("to_date")   or frappe.utils.today()

    recv_rows = frappe.db.sql(
        "SELECT r.posting_date, r.posting_time, r.farm AS farm,"
        "  r.custom_greenhouse AS greenhouse, r.custom_bucket_id AS bucket_id"
        " FROM `tabStock Entry` r"
        " WHERE r.stock_entry_type IN ('Receiving','Late Receipt') AND r.docstatus = 1"
        "   AND r.posting_date BETWEEN %(from_date)s AND %(to_date)s"
        "   AND r.custom_bucket_id > '' AND r.farm > '' AND r.custom_greenhouse > ''"
        " ORDER BY r.posting_date DESC, r.posting_time DESC LIMIT 20000",
        {"from_date": from_date, "to_date": to_date}, as_dict=1)

    rows_out = []
    if recv_rows:
        # Harvest + shelf lookups by date range (indexed), not by giant bucket IN
        # lists, so this scales for wide ranges.
        harvest_map = {}
        shelf_map = {}
        hrows = frappe.db.sql(
            "SELECT h.custom_bucket_id AS bucket_id, h.posting_date, h.posting_time"
            " FROM `tabStock Entry` h"
            " WHERE h.stock_entry_type = 'Harvesting' AND h.docstatus = 1"
            "   AND h.posting_date BETWEEN %(from_date)s AND %(to_date)s"
            "   AND h.custom_bucket_id > ''"
            " ORDER BY h.posting_time ASC",
            {"from_date": from_date, "to_date": to_date}, as_dict=1)
        for hr in hrows:
            k = str(hr.get("bucket_id") or "") + "|" + str(hr.get("posting_date") or "")
            if k not in harvest_map:
                harvest_map[k] = hr
        srows = frappe.db.sql(
            "SELECT si.bucket_id AS bucket_id, MIN(si.date_added) AS date_added"
            " FROM `tabShelf Item` si"
            " WHERE si.date_added >= %(from_date)s AND si.bucket_id > ''"
            " GROUP BY si.bucket_id",
            {"from_date": from_date}, as_dict=1)
        for sr in srows:
            shelf_map[str(sr.get("bucket_id") or "")] = sr.get("date_added")

        def fmt_time(t_val):
            if not t_val:
                return ""
            raw = str(t_val)
            if "," in raw:
                raw = raw.split(",")[1].strip()
            if "." in raw:
                raw = raw.split(".")[0]
            parts = raw.strip().split(":")
            if len(parts) == 3:
                return str(parts[0]).zfill(2) + ":" + str(parts[1]).zfill(2) + ":" + str(parts[2]).zfill(2)
            if len(parts) == 2:
                return str(parts[0]).zfill(2) + ":" + str(parts[1]).zfill(2) + ":00"
            return ""

        def to_dt(d, t):
            if not d or not t:
                return None
            try:
                return frappe.utils.get_datetime(str(d) + " " + fmt_time(t))
            except Exception:
                return None

        for r in recv_rows:
            k = str(r.get("bucket_id") or "") + "|" + str(r.get("posting_date") or "")
            h = harvest_map.get(k)
            if not h:
                continue
            hdt = to_dt(h.get("posting_date"), h.get("posting_time"))
            rdt = to_dt(r.get("posting_date"), r.get("posting_time"))
            if not hdt or not rdt:
                continue
            end_dt = rdt
            shelf_dt = shelf_map.get(str(r.get("bucket_id") or ""))
            if shelf_dt:
                try:
                    sdt = frappe.utils.get_datetime(str(shelf_dt))
                    if sdt > end_dt:
                        end_dt = sdt
                except Exception:
                    end_dt = end_dt
            m = int((end_dt - hdt).total_seconds()) // 60
            if m < 0 or m > 14400:
                continue
            rows_out.append({"greenhouse": r.get("greenhouse") or "", "farm": r.get("farm") or "",
                             "timeline_minutes": m})

    frappe.response["message"] = {"rows": rows_out, "total": len(rows_out)}
except Exception as e:
    frappe.log_error(str(e), "fetch_complete_timeline")
    frappe.response["message"] = {"rows": [], "error": str(e)}

# fetch_quarantine_dwell — Receiving Quarantined -> release, per greenhouse.
# Live schema (2026-09): entry type is 'Receiving Quarantined', exit/release is
# 'Quarantine Accept' (NOT 'Material Transfer' anymore). Link by custom_bucket_id.
# `farm` is NULL on both quarantine entry and accept rows, so derive it from the
# first token of custom_greenhouse (e.g. "Simotwo GH 05 - KR" -> "Simotwo").
try:
    from_date = frappe.form_dict.get("from_date") or frappe.utils.today()
    to_date   = frappe.form_dict.get("to_date")   or frappe.utils.today()

    def farm_of(gh):
        if not gh:
            return ""
        return str(gh).split(" ")[0]

    q_rows = frappe.db.sql(
        "SELECT q.posting_date, q.posting_time,"
        "  q.custom_greenhouse AS greenhouse, q.custom_bucket_id AS bucket_id"
        " FROM `tabStock Entry` q"
        " WHERE q.stock_entry_type = 'Receiving Quarantined' AND q.docstatus = 1"
        "   AND q.posting_date BETWEEN %(from_date)s AND %(to_date)s"
        "   AND q.custom_bucket_id > '' AND q.custom_greenhouse > ''"
        " ORDER BY q.posting_date DESC, q.posting_time DESC LIMIT 20000",
        {"from_date": from_date, "to_date": to_date}, as_dict=1)

    rows_out = []
    if q_rows:
        bucket_ids = []
        for r in q_rows:
            b = r.get("bucket_id") or ""
            if b and b not in bucket_ids:
                bucket_ids.append(b)

        def escape_list(items):
            parts = []
            for itm in items:
                parts.append(frappe.db.escape(itm))
            return ", ".join(parts)

        release_map = {}
        if bucket_ids:
            mrows = frappe.db.sql(
                "SELECT m.custom_bucket_id AS bucket_id,"
                "  MIN(TIMESTAMP(m.posting_date, SUBSTRING(m.posting_time,1,8))) AS release_dt"
                " FROM `tabStock Entry` m"
                " WHERE m.custom_bucket_id IN (" + escape_list(bucket_ids) + ")"
                "   AND m.stock_entry_type = 'Quarantine Accept' AND m.docstatus = 1"
                "   AND m.posting_date >= %(from_date)s"
                " GROUP BY m.custom_bucket_id",
                {"from_date": from_date}, as_dict=1)
            for mr in mrows:
                release_map[str(mr.get("bucket_id") or "")] = mr.get("release_dt")

        def fmt_time(t_val):
            if not t_val:
                return ""
            raw = str(t_val)
            if "," in raw:
                raw = raw.split(",")[1].strip()
            if "." in raw:
                raw = raw.split(".")[0]
            parts = raw.strip().split(":")
            if len(parts) == 3:
                return str(parts[0]).zfill(2) + ":" + str(parts[1]).zfill(2) + ":" + str(parts[2]).zfill(2)
            if len(parts) == 2:
                return str(parts[0]).zfill(2) + ":" + str(parts[1]).zfill(2) + ":00"
            return ""

        def mins_to_dt(d1, t1, dt2):
            if not d1 or not t1 or not dt2:
                return None
            try:
                x = frappe.utils.get_datetime(str(d1) + " " + fmt_time(t1))
                y = frappe.utils.get_datetime(str(dt2))
                return int((y - x).total_seconds()) // 60
            except Exception:
                return None

        for r in q_rows:
            rel = release_map.get(str(r.get("bucket_id") or ""))
            if not rel:
                continue
            m = mins_to_dt(r.get("posting_date"), r.get("posting_time"), rel)
            if m is None or m < 0 or m > 10080:
                continue
            gh = r.get("greenhouse") or ""
            rows_out.append({"greenhouse": gh, "farm": farm_of(gh),
                             "quarantine_minutes": m})

    frappe.response["message"] = {"rows": rows_out, "total": len(rows_out)}
except Exception as e:
    frappe.log_error(str(e), "fetch_quarantine_dwell")
    frappe.response["message"] = {"rows": [], "error": str(e)}

# fetch_intake_dwell — Receiving -> Shelving dwell, per greenhouse.
# Live schema: link by custom_bucket_id (not greenhouse+date, which caused the
# cartesian join / timeout). Late Receipt has no data on this site, so the
# meaningful intake dwell is Receive -> Shelf. Anchored on Receiving, batch
# Shelf Item lookup by bucket.
try:
    from_date = frappe.form_dict.get("from_date") or frappe.utils.today()
    to_date   = frappe.form_dict.get("to_date")   or frappe.utils.today()

    recv_rows = frappe.db.sql(
        "SELECT r.posting_date, r.posting_time, r.farm AS farm,"
        "  r.custom_greenhouse AS greenhouse, r.custom_bucket_id AS bucket_id"
        " FROM `tabStock Entry` r"
        " WHERE r.stock_entry_type IN ('Receiving','Late Receipt') AND r.docstatus = 1"
        "   AND r.posting_date BETWEEN %(from_date)s AND %(to_date)s"
        "   AND r.custom_bucket_id > '' AND r.farm > '' AND r.custom_greenhouse > ''"
        " ORDER BY r.posting_date DESC, r.posting_time DESC LIMIT 20000",
        {"from_date": from_date, "to_date": to_date}, as_dict=1)

    rows_out = []
    if recv_rows:
        # Shelf lookup bounded by date_added (shelving happens at/after receiving)
        # rather than a giant bucket IN list, so it scales for wide ranges.
        shelf_map = {}
        srows = frappe.db.sql(
            "SELECT si.bucket_id AS bucket_id, MIN(si.date_added) AS date_added"
            " FROM `tabShelf Item` si"
            " WHERE si.date_added >= %(from_date)s AND si.bucket_id > ''"
            " GROUP BY si.bucket_id",
            {"from_date": from_date}, as_dict=1)
        for sr in srows:
            shelf_map[str(sr.get("bucket_id") or "")] = sr.get("date_added")

        def fmt_time(t_val):
            if not t_val:
                return ""
            raw = str(t_val)
            if "," in raw:
                raw = raw.split(",")[1].strip()
            if "." in raw:
                raw = raw.split(".")[0]
            parts = raw.strip().split(":")
            if len(parts) == 3:
                return str(parts[0]).zfill(2) + ":" + str(parts[1]).zfill(2) + ":" + str(parts[2]).zfill(2)
            if len(parts) == 2:
                return str(parts[0]).zfill(2) + ":" + str(parts[1]).zfill(2) + ":00"
            return ""

        def mins_to_dt(d1, t1, dt2):
            if not d1 or not t1 or not dt2:
                return None
            try:
                x = frappe.utils.get_datetime(str(d1) + " " + fmt_time(t1))
                y = frappe.utils.get_datetime(str(dt2))
                return int((y - x).total_seconds()) // 60
            except Exception:
                return None

        for r in recv_rows:
            shelf_dt = shelf_map.get(str(r.get("bucket_id") or ""))
            if not shelf_dt:
                continue
            m = mins_to_dt(r.get("posting_date"), r.get("posting_time"), shelf_dt)
            if m is None or m < 0 or m > 10080:
                continue
            rows_out.append({"greenhouse": r.get("greenhouse") or "", "farm": r.get("farm") or "",
                             "dwell_minutes": float(m), "stage": "Shelving",
                             "workflow": "receive_to_shelving"})

    frappe.response["message"] = {"rows": rows_out, "total": len(rows_out)}
except Exception as e:
    frappe.log_error(str(e), "fetch_intake_dwell")
    frappe.response["message"] = {"rows": [], "error": str(e)}
